import{_ as i,C as r,o,c as l,j as e,a as s,E as h,a5 as d}from"./chunks/framework.D_J2JZBr.js";const E=JSON.parse('{"title":"EE291F 数字 VLSI 设计流程","description":"围绕 Linux、工程管理、工艺文件、时序、逻辑综合与形式等价理解数字芯片设计流程。","frontmatter":{"title":"EE291F 数字 VLSI 设计流程","description":"围绕 Linux、工程管理、工艺文件、时序、逻辑综合与形式等价理解数字芯片设计流程。"},"headers":[],"relativePath":"shanghaitech/courses/ee291f.md","filePath":"shanghaitech/courses/ee291f.md","lastUpdated":1795531638000}'),n={name:"shanghaitech/courses/ee291f.md"};function c(u,t,g,p,f,b){const a=r("CourseTable");return o(),l("div",null,[t[0]||(t[0]=e("h1",{id:"ee291f-数字-vlsi-设计流程",tabindex:"-1"},[s("EE291F 数字 VLSI 设计流程 "),e("a",{class:"header-anchor",href:"#ee291f-数字-vlsi-设计流程","aria-label":'Permalink to "EE291F 数字 VLSI 设计流程"'},"​")],-1)),h(a,{codes:"EE291F"}),t[1]||(t[1]=d('<p>课程表采用 <strong>2026–2027 学年</strong>信息；下文具体课件与作业依据娄鑫老师公开页的 <strong>2026 秋版本</strong>。往届版本教师可能不同；公开资源页不等于全学期内容都已列齐。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">EE113</a>让你理解门电路的代价，EE291F 则把设计放进可运行、可交接的数字工程流程：源代码怎样进入工具，约束怎样影响实现，工具产物怎样被下一阶段正确使用。</p><p>官方先修为 EE113。建议熟悉 HDL、组合 / 时序逻辑、时钟与建立保持时间，并具备基本编程能力。不要求在选课前“学完所有 EDA 软件”，但应愿意使用命令行、读日志、维护脚本。它与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 暑期实训</a>相互补充：本页公开的 2026 秋资料侧重工程基础、综合与形式等价，暑期实训经验覆盖更完整的物理实现与签核。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>公开课程页列出以下八组课件：</p><table tabindex="0"><thead><tr><th>顺序</th><th>主题</th><th>关键问题</th></tr></thead><tbody><tr><td>1</td><td>Linux</td><td>如何管理文件、进程、环境与批处理任务？</td></tr><tr><td>2</td><td>VLSI Overview &amp; EDA Tools</td><td>各阶段工具的职责与输入输出是什么？</td></tr><tr><td>3</td><td>Tcl、Git、Makefile</td><td>如何表达工具操作、管理版本与组织可重复运行？</td></tr><tr><td>4</td><td>Technology Files</td><td>工艺与库文件分别给工具提供什么信息？</td></tr><tr><td>5</td><td>Timing</td><td>时序路径和约束怎样定义“足够快”？</td></tr><tr><td>6</td><td>Genus 综合</td><td>RTL 如何转换为带约束的门级实现？</td></tr><tr><td>7</td><td>Design Compiler 综合</td><td>在另一套综合工具中理解同类任务</td></tr><tr><td>8</td><td>Formality 形式验证</td><td>如何检查综合前后的逻辑等价性？</td></tr></tbody></table><p>把时序约束看作设计契约，而不是为了得到漂亮报告而调整的参数。综合能完成，不代表约束完整；等价性通过，也不代表设计满足目标频率。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>2026 秋公开页的 EE291F / CX291F 共用作业包含：</p><ul><li><strong>HW1：Genus 综合流程</strong>。以 MohoTop 为对象，交付报告、综合网表、时序约束文件（SDC）与综合报告。</li><li><strong>HW2：DC 与 Formality 流程</strong>。完成综合与形式验证，提交报告、网表、SDC、标准延时格式（SDF）及工具报告。</li></ul><p>这些任务训练的不是记住一串命令，而是完整解释交付物。建议报告按“输入与配置 → 执行流程 → 检查结果 → 问题解释”组织；至少能够说明顶层模块、时钟约束、库配置、综合结果和等价性检查分别来自哪里。</p><p>进行工具对比时，必须对齐 RTL、库、约束、工艺角与统计口径。若条件不同，只能报告各自结果，不能直接宣称某工具更优。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li><a href="https://vsplab.cn/courses/ee291f/" target="_blank" rel="noreferrer">VSPLab EE291F 官方课程页</a>：Linux、工具、管理、工艺文件、Timing、Genus、DC、Formality 课件和当学期作业。</li><li>工具帮助与课程提供的授权文档：用于查询 Tcl 命令及报告字段，不转发受限文档包。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/knowledge-map">设计流程</a>：补充综合与物理设计的全局关系。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/tools/development/">EDA 环境</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/tools/eda/commercial">商业 EDA</a>：区分环境问题、许可证问题、输入问题与设计问题。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 秋版本。</strong> 公开页列出了两次作业及交付要求，但没有完整总评比例。本页不将两次作业等同于全部考核，也不推断是否有考试或期末项目。</p><ul><li><strong>难点</strong>：库与约束不匹配、未约束路径、工具运行环境，以及读懂综合和形式验证日志。</li><li><strong>准备</strong>：掌握 Linux 基本命令、Git、Makefile 与简单 Tcl。理解输入、输出、错误信息，比背一整份参考脚本更重要。</li><li><strong>调试</strong>：先判断错误属于读入、展开、约束、映射、优化还是验证。保留第一处有效错误及完整日志，不只看最后一句失败。</li><li><strong>可复现</strong>：区分源码、配置与运行目录；一次实验绑定一组明确输入。修改约束后重新标记结果，避免覆盖旧报告却继续引用旧网表。</li><li><strong>交付</strong>：用报告说明实际完成与未通过的检查，不把进程退出码为零当作设计验收。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA</a>：流程、优化和形式化方法。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI</a>：逻辑实现与时序收敛。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/eda/">EDA 学习地图</a>：从使用工具走向理解算法。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过这门课，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充注明学期的学习经验与公开资源。不要分享服务器入口、许可证配置或受限工艺文件。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://vsplab.cn/courses/ee291f/" target="_blank" rel="noreferrer">VSPLab EE291F 官方课程资源</a>：2026 秋八组课件与 HW1 / HW2。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：授课教师、学分与先修。</li></ul>',23))])}const k=i(n,[["render",c]]);export{E as __pageData,k as default};
